<!-- =========================================================
     TRUST STRIP
     ========================================================= -->
<section class="border-y border-bone-300 bg-white" aria-label="Our guarantees">
  <ul data-stagger class="mx-auto grid max-w-7xl grid-cols-2 divide-bone-200 px-4 sm:px-6 lg:grid-cols-4 lg:divide-x lg:px-8 [&>li>span:first-child]:transition-transform [&>li:hover>span:first-child]:-rotate-6 [&>li:hover>span:first-child]:scale-110">
    <li class="flex items-center gap-3 py-5 lg:px-6 lg:first:pl-0">
      <span class="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-halal-50 text-halal-600"><i data-lucide="shield-check" class="h-5 w-5" aria-hidden="true"></i></span>
      <span class="text-sm leading-snug"><strong class="block text-ink-900">100% Hand-Slaughtered</strong><span class="text-ink-500">Zabiha, Tasmiyah on every animal</span></span>
    </li>
    <li class="flex items-center gap-3 py-5 lg:px-6">
      <span class="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-saffron-300/30 text-saffron-600"><i data-lucide="bird" class="h-5 w-5" aria-hidden="true"></i></span>
      <span class="text-sm leading-snug"><strong class="block text-ink-900">Live Poultry Market</strong><span class="text-ink-500">Pick your bird, slaughtered fresh</span></span>
    </li>
    <li class="flex items-center gap-3 py-5 lg:px-6">
      <span class="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-sky-50 text-sky-600"><i data-lucide="snowflake" class="h-5 w-5" aria-hidden="true"></i></span>
      <span class="text-sm leading-snug"><strong class="block text-ink-900">Temperature-Controlled</strong><span class="text-ink-500">0–4 °C insulated delivery</span></span>
    </li>
    <li class="flex items-center gap-3 py-5 lg:px-6">
      <span class="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-brand-50 text-brand-600"><i data-lucide="scan-line" class="h-5 w-5" aria-hidden="true"></i></span>
      <span class="text-sm leading-snug"><strong class="block text-ink-900">Farm-Traceable</strong><span class="text-ink-500">Batch & farm on every label</span></span>
    </li>
  </ul>
</section>

