  <div class="pointer-events-none absolute inset-y-0 right-0 z-10 w-24 bg-gradient-to-l from-brand-800 to-transparent"></div>
  <div class="marquee flex w-max items-center whitespace-nowrap font-display text-2xl italic sm:text-3xl [&>span]:pr-10">
